# Inglenook for Docker build output: Inglenook Day.
# Source this from your profile. Needs Docker with BuildKit (Docker 23 or newer).
# The names are terminal colors: set your terminal to Inglenook Day too.
# Palette 1.0.0, https://github.com/mookeyj79/Inglenook

# run: finished steps. cancel: canceled steps. warning: steps with a warning.
# error: the step that failed.
export BUILDKIT_COLORS='run=green:cancel=yellow:warning=yellow:error=red'
